describe('Form Auto-Save as Draft', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should auto-save form as draft every 30 seconds', () => {
    // Fill form with initial data
    cy.get('[data-testid="form-input-name"]').type('John Doe');
    cy.get('[data-testid="form-input-email"]').type('john@example.com');
    cy.get('[data-testid="form-input-message"]').type('This is a test message for auto-save.');

    // Verify form is not yet saved
    cy.get('[data-testid="save-status"]').should('contain', 'Unsaved');

    // Wait for the first auto-save interval (30 seconds)
    cy.wait(31000);

    // Verify form is saved as draft
    cy.get('[data-testid="save-status"]').should('contain', 'Saved as Draft');
    cy.get('[data-testid="draft-indicator"]').should('be.visible');

    // Modify form data
    cy.get('[data-testid="form-input-name"]').clear().type('Jane Doe');
    cy.get('[data-testid="form-input-email"]').clear().type('jane@example.com');

    // Wait for the second auto-save interval
    cy.wait(31000);

    // Verify form is updated and saved as draft
    cy.get('[data-testid="save-status"]').should('contain', 'Saved as Draft');
    cy.get('[data-testid="draft-indicator"]').should('be.visible');
    cy.get('[data-testid="form-input-name"]').should('have.value', 'Jane Doe');
  });

  it('should not auto-save when form is empty or disabled', () => {
    // Verify form is not saved when empty
    cy.get('[data-testid="save-status"]').should('contain', 'Unsaved');

    // Wait for the first auto-save interval
    cy.wait(31000);

    // Verify form is still not saved
    cy.get('[data-testid="save-status"]').should('contain', 'Unsaved');
    cy.get('[data-testid="draft-indicator"]').should('not.exist');

    // Disable form inputs
    cy.get('[data-testid="form-input-name"]').click();
    cy.get('[data-testid="form-input-name"]').should('be.disabled');
    cy.get('[data-testid="form-input-email"]').should('be.disabled');

    // Wait for the auto-save interval while disabled
    cy.wait(31000);

    // Verify form is still not saved
    cy.get('[data-testid="save-status"]').should('contain', 'Unsaved');
    cy.get('[data-testid="draft-indicator"]').should('not.exist');

    // Enable form inputs
    cy.get('[data-testid="form-input-name"]').should('not.be.disabled');
    cy.get('[data-testid="form-input-email"]').should('not.be.disabled');

    // Fill form with data
    cy.get('[data-testid="form-input-name"]').type('Test User');
    cy.get('[data-testid="form-input-email"]').type('test@example.com');

    // Wait for auto-save
    cy.wait(31000);

    // Verify form is saved as draft
    cy.get('[data-testid="save-status"]').should('contain', 'Saved as Draft');
    cy.get('[data-testid="draft-indicator"]').should('be.visible');
  });
});
